/* Optional local prototype checks; not loaded by the normal page. */
window.checkPcReference = async function checkPcReference() {
  if(location.hostname!=='127.0.0.1'||location.port!=='4179'||!document.title.includes('参考页面'))throw new Error('Local reference page only');
  const checks=[];
  const tick=()=>new Promise(r=>setTimeout(r,50));
  const assert=(name,condition)=>{checks.push({name,pass:!!condition});if(!condition)throw new Error(name);};
  const text=()=>document.querySelector('main').innerText;
  const click=async selector=>{const el=document.querySelector(selector);if(!el||el.disabled)throw new Error(`Missing control ${selector}`);el.click();await tick();};
  const action=id=>click(`[data-action="${id}"]`);
  const route=async hash=>{location.hash=hash;await tick();};
  const input=(selector,value)=>{const el=document.querySelector(selector);el.value=value;el.dispatchEvent(new Event('input',{bubbles:true}));};
  const choice=value=>{const el=document.querySelector('#buy-timing');el.value=value;el.dispatchEvent(new Event('change',{bubbles:true}));};
  const reset=async()=>{await action('about');await action('reset');};
  const routePrices=()=>[...document.querySelectorAll('.buy-price')].map(el=>Number(el.textContent.replace(/[^\d]/g,'')));
  const rowModels=()=>[...document.querySelectorAll('.buy-row strong')].map(el=>el.textContent).sort((a,b)=>a.localeCompare(b)).join('|');
  const summaryPrice=()=>Number(document.querySelector('.purchase-summary .price').textContent.replace(/[^\d]/g,''));
  try{
    await reset();
    assert('opens the actual computer plan, not a dashboard',document.querySelector('h1').textContent==='配一台新电脑');
    assert('waiting for family is normal, not a blocked task',text().includes('正在和家人商量')&&!text().includes('待审批')&&!text().includes('执行失败'));
    assert('four core parts visible, secondary four collapsed',document.querySelectorAll('.config-list:first-of-type .component-row').length>=4&&document.querySelector('#extra-components').hidden);
    assert('price freshness and no monitoring stated',text().includes('9 月 17 日')&&text().includes('不会自动监控'));
    await action('expand-config');
    assert('full eight parts can be expanded',!document.querySelector('#extra-components').hidden&&document.querySelectorAll('.component-row').length===8);
    await action('expand-config');
    assert('extra configuration can be collapsed',document.querySelector('#extra-components').hidden);
    await route('computer/buy');
    assert('saving route shows two shops and eight parts',document.querySelectorAll('.shop-heading').length===2&&document.querySelectorAll('.buy-row').length===8);
    assert('saving total calculated from actual displayed lines',summaryPrice()===9260&&routePrices().reduce((a,b)=>a+b,0)===summaryPrice());
    const models=rowModels();
    await click('[data-route="easy"]');
    assert('convenience route shows one shop, same eight parts',document.querySelectorAll('.shop-heading').length===1&&models===rowModels());
    assert('alternative sum consistent with all line prices',summaryPrice()===9680&&routePrices().reduce((a,b)=>a+b,0)===summaryPrice());
    assert('viewing route is not purchase intent',text().includes('不会替你作购买决定'));
    await click('[data-action="product"][data-part="board"]');
    assert('product detail explicitly sample, no fake external shop link',document.querySelector('dialog').open&&document.querySelector('#modal-body').textContent.includes('没有真实商品链接')&&document.querySelector('#modal-body').textContent.includes('BIOS'));
    await action('close');
    await route('computer');
    assert('route browsing did not change undecided intent',document.querySelector('.situation').textContent.includes('正在和家人商量'));
    await action('focus-note');
    assert('record-result action takes focus straight to writing',document.activeElement.id==='note');
    document.querySelector('#note-form').requestSubmit();await tick();
    assert('blank save provides recovery, no empty record',document.querySelector('#note-error').textContent.length>0&&!document.querySelector('.saved-note'));
    input('#note','先等周末商量，不要下单。');
    choice('later');
    await route('computer/buy');await route('computer');
    assert('unsaved note and explicit choice survive page switching',document.querySelector('#note').value==='先等周末商量，不要下单。'&&document.querySelector('#buy-timing').value==='later');
    assert('unsaved choice does not yet change current situation',document.querySelector('.situation').textContent.includes('正在和家人商量'));
    document.querySelector('#note-form').requestSubmit();await tick();
    assert('saved note updates intention only',document.querySelector('.situation').textContent.includes('决定再等等')&&document.querySelector('.saved-note').textContent.includes('不要下单'));
    assert('saved intention has no implicit purchase or price automation',text().includes('没有下单、预约或启动比价')&&text().includes('¥9,260'));
    await route('home');
    assert('home reflects the same current decision',text().includes('决定再等等'));
    await route('computer/family');
    assert('family summary includes recorded decision and budget limits',text().includes('先等周末商量')&&text().includes('不含显示器')&&text().includes('没有可靠依据断言'));
    await action('family-copy');
    assert('family sharing is manual selection, not automatic send',document.querySelector('#copy-text').value.includes('虚构页面示例')&&document.querySelector('#modal-body').textContent.includes('没有自动发送'));
    await action('select-copy');
    assert('selection does not need clipboard access',document.querySelector('#copy-text').selectionEnd===document.querySelector('#copy-text').value.length);
    await action('close');
    await route('computer');await action('handoff');
    assert('handoff contains current need and no purchase authority',document.querySelector('#copy-text').value.includes('准备稍后购买')&&document.querySelector('#copy-text').value.includes('没有下单、付费'));
    await action('close');await action('edit-note');
    input('#note','<img src=x onerror=alert(1)> 只记一条想法。');
    document.querySelector('#note-form').requestSubmit();await tick();
    assert('user text escaped, not executable markup',document.querySelector('.saved-note p').textContent.includes('<img')&&!document.querySelector('.saved-note img'));
    await route('computer/history');
    assert('history distinguishes user notes and agent sample conclusions',text().includes('你（仅预览）')&&text().includes('Agent 整理（样例）'));
    assert('editing a note preserves earlier recorded content',text().includes('先等周末商量，不要下单。'));
    await action('search');input('#search-input','不存在的标题');
    assert('empty search has understandable recovery copy',document.querySelector('#search-results').textContent.includes('试试其他关键词'));
    input('#search-input','配一台');
    assert('search finds direct page',document.querySelectorAll('#search-results a').length===1);
    await click('#search-results a');
    assert('search opens the page and closes modal',!document.querySelector('dialog').open&&document.querySelector('h1').textContent==='配一台新电脑');
    await action('navigation');
    assert('mobile navigation exposes page titles, not work categories',document.querySelector('#modal-body').textContent.includes('配一台新电脑')&&document.querySelector('#modal-body').textContent.includes('周末去哪里'));
    await click('#modal-body a[href="#page/weekend"]');
    assert('switching opens a directly writable document',document.querySelector('#page-title').value==='周末去哪里'&&!!document.querySelector('#page-body'));
    input('#page-body','修改一条自己的笔记。');await action('save-page');await route('computer');await route('page/weekend');
    assert('local notes survive navigation without starting work',document.querySelector('#page-body').value==='修改一条自己的笔记。');
    await action('new');
    assert('new page focuses the obvious title field',document.activeElement.id==='page-title'&&document.querySelector('#page-title').value==='');
    input('#page-title','测试新笔记');input('#page-body','只写下来，不自动执行。');await action('save-page');
    assert('new title appears in navigation',document.querySelector('#sidebar').textContent.includes('测试新笔记'));
    await route('home');
    assert('new page is reachable from home',text().includes('测试新笔记'));
    input('#quick-note','下周想看的展览');document.querySelector('#quick-form').requestSubmit();await tick();
    assert('home quick entry creates a writable page',document.querySelector('#page-title').value==='下周想看的展览');
    await route('computer');
    const before=location.hash;await click('a.skip');
    assert('skip link does not replace the current page',location.hash===before&&document.activeElement.id==='content');
    await reset();
    for(const page of ['computer','computer/buy','computer/family','computer/history','home','all','page/weekend','page/reading']){
      await route(page);
      assert(`no horizontal overflow: ${page}`,document.documentElement.scrollWidth<=innerWidth);
      assert(`one main heading: ${page}`,document.querySelectorAll('main h1').length===1);
    }
    await route('computer');await action('expand-config');
    assert('expanded configuration also fits viewport',document.documentElement.scrollWidth<=innerWidth);
    await action('expand-config');await action('about');
    assert('modal fits viewport',document.querySelector('dialog').scrollWidth<=innerWidth&&document.querySelector('dialog').getBoundingClientRect().height<=innerHeight);
    await action('close');
    const remote=performance.getEntriesByType('resource').filter(r=>!r.name.startsWith(location.origin+'/'));
    assert('all resource requests local',remote.length===0);
    return {viewport:[innerWidth,innerHeight],passed:checks.length,failed:0,checks};
  }catch(error){return {viewport:[innerWidth,innerHeight],passed:checks.filter(c=>c.pass).length,failed:1,error:String(error),checks};}
};
